create table public.lessons(id uuid primary key default gen_random_uuid(),title text not null,category text not null,description text not null default '',steps jsonb not null default '[]' check(jsonb_typeof(steps)='array'),status text not null default 'draft' check(status in ('draft','published'))); alter table public.lessons enable row level security; revoke all on public.lessons from public,anon,authenticated;;
